Method.Implementation:
s prg=" util.ie.datacite.duiProcess "
w !,prg_"execute id="_id

n sUser s sUser="dui_datacite" ; pro CavUnEpca.userIsAdmin() aby se dalo zapsat DOI do 017

s ret=""        ; do DUI nevracet chybu, pri chybe se zapise znovu s casovou znackou
q:id="" ret
q:list="" ret
q:'$lv(list) ret

s bDone=0
try {                     ; abychom neshodili DUI
  s idx=$li(list,2)
  s loop=$li(list,3)+1    ; kolikaty bezi pokus DUI o zpracovani
  s op=$li(list,4)
  s event=$li(list,5)
  s urlType=$li(list,6)
  s doi=$li(list,7)
  s class=##class(User.Util).lname2objectName($p(idx,"*"))
  s ipref=##class(User.Util).getClassPrefixParam(class)
  w !,"  loop="_loop_", idx="_idx_", DOI="_doi_", operation="_op_", event="_event_", urlType="_urlType

  ; 18.11.25 jk; pridana moznost zapnout/vypnout zpracovani
  s bOn=+##class(User.Util).sXlate("ARL_CFG","DataciteDOI","N",ipref)
  if 'bOn { 
    w !,"  Datacite process is OFF (check the ARL_CFG DataciteDOI)"
    s bDone=1   ; vyhodime z DUI
    q 
  }      

  if (op="delete")||((op="updateUrl")&&(urlType="deleted"))  {
    ; operace u kterych nemame handle (zaznam byl vymazan z DB)
    if op="updateUrl" {
      ; pro urlType="deleted"
      s bUp=..updateDoiUrl(ipref,doi,idx,urlType)
      if bUp {
        w !,"  the DataCite url updated succesfully"
        s bDone=1
      }
    }
    elseif op="delete" {
      s bDel=..deleteDoi(ipref,doi)   ; pocita se ze zaznam je uz vymazan
      if bDel {
        w !,"  the DataCite delete DOI succesfully"
        s bDone=1
      }
    }
  }
  else {

    if '##class(User.MARC).readLX(.handle,idx,"T") {
      w !,"  ERRDATACITE002 error readX idx="_idx
      ; potrebujeme mit zaznam ulozeny v db, pokud by nahodou DUI predbehnula ulozeni zaznamu, udelame 2 pokusy o zpracovani
      s:loop>1 bDone=1 ; probehnul druhy pokus, vyhodime z DUI
      q
    }

    s err=..checking(ipref,.handle,op,event)
    if err'="" {
      w !,"  "_err
      s bDone=1        ; vyhodime z DUI
      q
    }

    if op="create" {
      s doi=..createDoi(ipref,.handle,event)
      if doi'="" {
        ; aktualizace DOI v zaznamu, zatim pro Unimarc
        s s017="017 7  "_$c(31)_"a"_doi_$c(31)_"2DOI"
        d $$$setTagX(.handle,s017)
        s sc=##class(User.MARC).writeX(.handle,1,1,0,3_$c(10)_"datacite"_$c(10)_"127.0.0.1")
        if $$$ISERR(sc) { w !,"  ERRDATACITE006 add new DOI to record, writeX sc="_##class(User.Util).status2str(sc) }  ; z DUI musime vyhodit, takze uspesne zpracovani
        else { w !,"  new DOI added to MARC record" }

        s bDone=1
      }
    }
    else {
      s doi=..getDoiFromHandle(ipref,.handle,.bDataCiteDoi)

      if op="update" {
        s bUp=..updateDoi(ipref,doi,.handle,event)
        if bUp {
          w !,"  the DataCite metadata updated succesfully"
          s bDone=1
        }
      }
      elseif op="updateState" {
        s bUp=..updateDoiState(ipref,doi,event)
        if bUp {
          w !,"  the DataCite state updated succesfully"
          s bDone=1
        }
      }
      elseif op="updateUrl" {
        ; pro urlType="persistent"
        s bUp=..updateDoiUrl(ipref,doi,idx,urlType)
        if bUp {
          w !,"  the DataCite url updated succesfully"
          s bDone=1
        }
      }
    }
  }
}
catch exp {
  w !,"  ERRDATACITE001#exception:"_exp.Name_exp.Location_", "_$SYSTEM.Status.Error(exp.Code,exp.Data) 
}

if 'bDone {
  ; neuspesne provolani
  s stamp=$zdt(##class(User.Util).dateHdtAdd($h,(3600*4)),3,1)   ; dalsi pokus za 4 hodiny, z DUI se nevyhazuje
  s $li(list)=stamp
  s $li(list,3)=$li(list,3)+1  ; loop
  s newId=##class(User.ChangeLog).dataciteDuiEnqueue(list)
  w !,"  unprocessed, inserted back to dui new id="_newId
}

q ret

s ret=""
; po UTF konverzi neni spravna diakritka napr. kdyz se ulozi body do globalu, ale v datacite Fabrica je OK
s body=$$$ToUTF8(..handle2json(ipref,.handle,event)) 
#dim req As %Net.HttpRequest
s req=..getHttpRequest(ipref)
d req.EntityBody.Write(body)
s sc=req.Post("/dois")
if $$$ISERR(sc) {
  w !,"  ERRDATACITE003 createDoi %Net.HttpRequest POST API datacite request error: "_##class(User.Util).status2str(sc)
  q ret
}
s st=req.HttpResponse.StatusCode
if st'="201" {
  w !,"  ERRDATACITE004 createDoi %Net.HttpRequest POST API datacite http status code: "_req.HttpResponse.StatusCode_" "_req.HttpResponse.StatusLine
  ; detail chyby 
  s streamHttp=req.HttpResponse.Data
  s response=streamHttp.Read(streamHttp.Size)
  w !,response,!
  s obj=##class(%DynamicAbstractObject).%FromJSON(response)
  if $isobject(obj) {
    ; format chybove odpoved {"errors":[{"status":400,"title":"No valid prefix found"}]}
    s iter=obj.errors.%GetIterator()
    while iter.%GetNext(.key, .value, .type ) {
      w !,"  status: "_value.status,"  title: "_value.title
    }
  }
  else {
    w !,"  no JSON response"
  }
  q ret
}

; odpoved vraci vsechna metada nove prirazenemu DOI, coz nevyuzijeme
s streamHttp=req.HttpResponse.Data
s response=streamHttp.Read(streamHttp.Size)

s obj=##class(%DynamicAbstractObject).%FromJSON(response)
if '$isobject(obj) {
  ; tohle by nemelo nastat, potrebujeme precist prirazene DOI
  w !,"  ERRDATACITE005 createDoi %Net.HttpRequest POST API datacite no JSON response"
  q ret
}
s ret=obj.data.attributes.doi  
w !,"  new registered DOI="_ret
q ret

s ret=0
; po UTF konverzi neni spravna diakritka napr. kdyz se ulozi body do globalu, ale v datacite Fabrica je OK
s body=$$$ToUTF8(..handle2json(ipref,.handle,event))
#dim req As %Net.HttpRequest
