s streamHttp=req.HttpResponse.Data
s response=streamHttp.Read(streamHttp.Size)

s obj=##class(%DynamicAbstractObject).%FromJSON(response)
if '$isobject(obj) {
  ; tohle by nemelo nastat, potrebujeme precist prirazene DOI
  w !,"  ERRDATACITE005 updateDoi %Net.HttpRequest POST API datacite no JSON response"
