s response=streamHttp.Read(streamHttp.Size)

s obj=##class(%DynamicAbstractObject).%FromJSON(response)
if '$isobject(obj) {
  ; tohle by nemelo nastat
  w !,"  ERRDATACITE005 updateDoiState %Net.HttpRequest POST API datacite no JSON response"
