s ret=0
s hlink=""

; The landing page
; s Cav dohodnuto ze pujde o persistentni link do IPACu, url je stejne jako pro handle.net
s ictx=$zcvt(ipref,"l")
s language=+##class(User.Util).getServerLanguage(ipref)
d ##class(i2.init).batchinit(ictx,language)
s sBaseURL=##class(i2.html.tpl).getBaseURL()
if urlType="deleted" {
  s confT001="CREDENTIALS_"_$zcvt(ipref,"u")
  s key="datacite"
  s:##class(User.Util).onTestNamespace() key=key_"_test"
  s urldel=##class(User.Util).sXlate(confT001,key,"SN",ipref,"i",,"CmSecurity")     ; url na stranku smazane zaznamy, bez base URL
  s hlink=sBaseURL_urldel
}
else {
  ; linku na detail zaznamu v ipacu 
  s hlink=sBaseURL_##class(i2.html.tpl).getRecordURL(idx)
  s hlink=##class(User.Util).strswap(hlink,"&amp;","&")
}

k %ipac2 ; pokusime se hned po sobe uklidit, jsme totiz v DUI, deinicializace

s obj={
  "data": {
      "type": "dois",
      "attributes": {
          "url": (hlink)
      }
  }}
; po UTF konverzi neni spravna diakritka napr. kdyz se ulozi body do globalu, ale v datacite Fabrica je OK
s body=$$$ToUTF8(obj.%ToJSON())

#dim req As %Net.HttpRequest
s req=..getHttpRequest(ipref)
d req.EntityBody.Write(body)
s sc=req.Put("/dois/"_doi)
if $$$ISERR(sc) {
