  q ret
}
s st=req.HttpResponse.StatusCode
if st'="200" {
  w !,"  ERRDATACITE004 updateDoiUrl %Net.HttpRequest POST API datacite http status code: "_req.HttpResponse.StatusCode_" "_req.HttpResponse.StatusLine
  ; detail chyby 
  s streamHttp=req.HttpResponse.Data
  s response=streamHttp.Read(streamHttp.Size)
  w !,response,!
  s obj=##class(%DynamicAbstractObject).%FromJSON(response)
  if $isobject(obj) {
    ; format chybove odpoved {"errors":[{"status":400,"title":"No valid prefix found"}]}
    s iter=obj.errors.%GetIterator()
    while iter.%GetNext(.key, .value, .type ) {
      w !,"  status: "_value.status,"  title: "_value.title
    }
  }
  else {
    w !,"  no JSON response"
  }
  q ret
}

