s ret=0
#dim req As %Net.HttpRequest
s req=..getHttpRequest(ipref)
s sc=req.Delete("/dois/"_doi)
if $$$ISERR(sc) {
  s err="  ERRDATACITE003 deleteDOI %Net.HttpRequest POST API datacite request error: "_##class(User.Util).status2str(sc)
  w !,err
  q
}
s st=req.HttpResponse.StatusCode
if st'="204" {
  w !,"  ERRDATACITE004 deleteDOI %Net.HttpRequest POST API datacite http status code: "_req.HttpResponse.StatusCode_" "_req.HttpResponse.StatusLine
  ; detail chyby 
  s streamHttp=req.HttpResponse.Data
  s response=streamHttp.Read(streamHttp.Size)
  s obj=##class(%DynamicAbstractObject).%FromJSON(response)
  if $isobject(obj) {
    ; format chybove odpovedi: {"errors":[{"status":"404","title":"The resource you are looking for doesn't exist."}]}
    s iter=obj.errors.%GetIterator()
    while iter.%GetNext(.key, .value, .type ) {
      w !,"  status: "_value.status,"  title: "_value.title
    }
  }
  else {
    w !,"  no JSON response"
  }
  q ret
}

