s type=##class(User.MARC).recordDataFmtX(.handle,.subfmt)

s confT001="CREDENTIALS_"_$zcvt(ipref,"u")
s key="datacite"
s:##class(User.Util).onTestNamespace() key=key_"_test"
s providerId=##class(User.Util).sXlate(confT001,key,"SN",ipref,"c",,"CmSecurity")
s clientId=##class(User.Util).sXlate(confT001,key,"SN",ipref,"d",,"CmSecurity")
s prefix=##class(User.Util).sXlate(confT001,key,"SN",ipref,"f",,"CmSecurity")
s suffix=##class(User.Util).sXlate(confT001,key,"SN",ipref,"g",,"CmSecurity")
s publisher=##class(User.Util).sXlate(confT001,key,"SN",ipref,"h",,"CmSecurity")

if suffix'="" { s suffix=$replace(suffix,"%T001%",$$$HandleT001(handle)) }  ; substituce %T001%

d ..handle2jsonPrepare(ipref,.handle,.tmp)

; schema metadat je zde https://schema.datacite.org/
; interaktivni vyplneni https://support.datacite.org/reference/post_dois
s obj={}
s data={}
s obj.data=data

s data.type="dois"

s attrib={}
s data.attributes=attrib
s:publisher'="" data.attributes.publisher=publisher  ; z CREDENTIALS

if suffix="" { s attrib.prefix=prefix }  ; sufix vygeneruje datacite
else { s attrib.doi=prefix_"/"_suffix }  ; vytvorime si cele DOI

s:event="draft" event=""  ; event pro draft se do API nevklada
s:event'="" attrib.event=event

s idfs=[]
if $g(tmp("handle.net"))'="" {
  ; v CavUnEpca je v subjects
  s hnd ={}
  s hnd.identifierType="Handle.Net"
  s hnd.identifier=tmp("handle.net")
  d idfs.%Push(hnd)
}
s:idfs.%Size() data.attributes.identifiers=idfs

; plneni dat autoru
s creators=[]
if ($g(tmp("autori","pocet"),-1)>=0)
{ 
  for i=0:1:tmp("autori","pocet") {
    s creator={
        "nameType": "Personal",
        "name": (tmp("autor",i,"celejmeno")),
        "givenName": (tmp("autor",i,"jmeno")),
        "familyName": (tmp("autor",i,"prijmeni"))          
      }    
    if ($g(tmp("autor",i,"ror"))'="") {
      s affs=[]
      s affiliation={
          "affiliationIdentifier": (tmp("autor",i,"ror")),
          "affiliationIdentifierScheme": "ROR",               ; musi byt vyplneno
          "name": ($g(tmp("autor",i,"rornazev"))),
          "schemeUri": "https://ror.org"
        }
      d affs.%Push(affiliation)
      s creator.affiliation=affs
    }

    s nameIds=[]
    if ($g(tmp("autor",i,"orcid"))'="") {
      ; export orcid - s:(sOrcid'="") tmp("autor",pocetAutoru,"orcid")="https://orcid.org"">https://orcid.org/"_sOrcid
      s ni= {
          "schemeUri": "https://orcid.org",
          "nameIdentifier": (tmp("autor",i,"orcid")),
          "nameIdentifierScheme": "ORCID"                     ; musi byt vyplneno
        }
      d nameIds.%Push(ni)
    }
    if ($g(tmp("autor",i,"wos"))'="") {
     ; export wos -     s:(sWOS'="") tmp("autor",pocetAutoru,"wos")="https://www.webofscience.com/wos/author/record/"_sWOS
     s ni= {
          "nameIdentifier": (tmp("autor",i,"wos")),
          "nameIdentifierScheme": "Other"                     ; musi byt vyplneno
          }
     d nameIds.%Push(ni)      
    }    
    if ($g(tmp("autor",i,"scopus"))'="") {
      ; export scopus -     s:(sSCOPUS'="") tmp("autor",pocetAutoru,"scopus")="https://www.scopus.com/authid/detail.uri?authorId="_sSCOPUS
      s ni= {
          "nameIdentifier": (tmp("autor",i,"scopus")),
          "nameIdentifierScheme": "Other"                     ; musi byt vyplneno
          }
      d nameIds.%Push(ni)      
    }
    s:nameIds.%Size() creator.nameIdentifiers=nameIds   

    d creators.%Push(creator)
  }
}
s:creators.%Size() data.attributes.creators=creators  

s titles=[]
if (($g(tmp("nazev"))'="")&&($g(tmp("nazevPreklad"))'="")) {
  ; nazev cesky
  s title={ "lang": "cs", "title": (tmp("nazev")) }
  d titles.%Push(title)
}
elseif (($g(tmp("nazev"))'="")&&($g(tmp("nazevPreklad"))="")) {
  ; nazev anglicky
  s title={"lang": "en", "title": (tmp("nazev")) }
  d titles.%Push(title)
}  
if ($g(tmp("nazevPreklad"))'="") {
  ; preklad nazvu
  s title={"lang": "en", "title": (tmp("nazevPreklad")),"titleType": "TranslatedTitle" }
  d titles.%Push(title)
}
if ($g( tmp("nazevAlternativni"))'="") {
  ; preklad nazvu
  s title={"lang": "", "title": (tmp("nazevAlternativni")),"titleType": "AlternativeTitle" }
  d titles.%Push(title)
}
s:titles.%Size() data.attributes.titles=titles

s pubYear=$g(tmp("rokPublikace"))
s:pubYear'="" data.attributes.publicationYear=pubYear

s subjects=[]
if ($g(tmp("subjekt"))=1) {
  s caa=0
  do { ; cyklus pres vsechny ID
    s sT610=$$$getTagXC(.handle,"610",.caa) ; vsechny ID
    continue:((sT610="")&&(caa'=0))

    s sT610a=$$$getSubTagStr(sT610,"a")
    if (sT610a'="") {
      ; 22.05.26 jk; vymazat formatovaci znaky
      d ##class(rep.epca.exportBase).symClearFormatInfoStr(.sT610a)
      s subject={"subject": (sT610a)}
      d subjects.%Push(subject)
    }
  } while (caa'=0)

  if ($g(data("C26y"))'="") {  
    s data("C26y")="FOS: "_data("C26y")
    s subject={
        "subject": (data("C26y")),
        "valueUri": "http://www.oecd.org/science/inno/38235147.pdf",
        "schemeUri": "http://www.oecd.org/science/inno",
        "subjectScheme": "Fields of Science and Technology (FOS)"
      }      
    d subjects.%Push(subject)
  }
}
s:subjects.%Size() data.attributes.subjects=subjects

if $g(tmp("jazyk"))'="" {
  s data.attributes.language=tmp("jazyk")
}

; podle https://datacite-metadata-schema.readthedocs.io/en/4.6/properties/resourcetype/
; se pouzivaji uz jen resourceType a resourceTypeGeneral
; zatim necham tak

; kompletni prevod pro typy ktere mame v 608a a jdou do XML v exportDataciteXmlHandle(), podle AI: 
; 608a  DataCite     RIS    BibTeX                 CiteProc          SchemaOrg
; ----  --------     ---    ------                 --------          ---------
; DS    Dataset      DATA   @misc                  dataset           Dataset
; TX    Text         GEN    @misc nebo @article    document          CreativeWork
; OBR   Image        FIGURE @misc                  figure            ImageObject
; VI    Audiovisual  VIDEO  @misc                  video             VideoObject
; AUD   Sound        SOUND  @misc                  song nebo speech  AudioObject
; SW    Software     COMP   @misc                  book nebo article SoftwareSourceCode

s data.attributes.types={
    "ris": "DATA",                
    "bibtex": "misc",             
    "citeproc": "dataset",       
    "schemaOrg": "Dataset",      
    "resourceType": "Dataset",
    "resourceTypeGeneral": "Dataset"
  }

s sizes=..getCsSizes(.handle)
if sizes.%Size() {
   s data.attributes.sizes=sizes
}

; U22 casove obdobi od/do, format datumu YYYY-MM-DD nebo YYYY
s sU22=##class(User.MARC).getTagX(.handle,"U22")
s sDatumOd=$e($$$getSubTagStr(sU22,"a"),1,8)
s sDatumDo=$e($$$getSubTagStr(sU22,"b"),1,8)
if $l(sDatumOd)=8 { s sDatumOd=$e(sDatumOd,1,4)_"-"_$e(sDatumOd,5,6)_"-"_$e(sDatumOd,7,8) }
if $l(sDatumDo)=8 { s sDatumDo=$e(sDatumDo,1,4)_"-"_$e(sDatumDo,5,6)_"-"_$e(sDatumDo,7,8) }
s dateCoverage=sDatumOd
if sDatumDo'="" {
  s:dateCoverage'="" dateCoverage=dateCoverage_"/"
  s dateCoverage=dateCoverage_sDatumDo
}
if (dateCoverage'="") {
  s dates=[]
  s date={}
  s date.date=dateCoverage
  s date.dateType="Coverage"
  d dates.%Push(date)
  s data.attributes.dates=dates
}

s data.attributes.formats=["json"]

s verze=$g(tmp("verze"))
s:verze'="" data.attributes.version=$g(tmp("verze"))

d ..getLicense(.handle,.license)
if license.%Size() {
  s rightsList=[]
  d rightsList.%Push(license)
  s data.attributes.rightsList=rightsList
}

s descriptions=[]
d:($g(tmp("abstractCz"))'="") descriptions.%Push({
       "lang": "cs",
       "description": (tmp("abstractCz")),
       "descriptionType": "Abstract"                    ; musi byt vyplneno
})  
d:($g(tmp("abstractEn"))'="") descriptions.%Push({
   "lang": "en",
   "description": (tmp("abstractEn")),
   "descriptionType": "Abstract"                        ; musi byt vyplneno
})
s:descriptions.%Size() data.attributes.descriptions=descriptions

; geoLocationPlace 617a, 617d
s c=0
s geoLocations=[]
do {
  s s617=$$$getTagXC(.handle,"617",.c)
  continue:s617=""

  s geoA=$$$getSubTagStr(s617,"a")
  s geoD=$$$getSubTagStr(s617,"d")
  s geo=geoA
  if geoD'="" {
    s:geo'="" geo=geo_", "
    s geo=geo_geoD
  }  
  if geo'="" {
    d geoLocations.%Push({
       "geoLocationPlace": (geo)
    })
  }
} while c'=0
s:geoLocations.%Size() data.attributes.geoLocations=geoLocations

s fundingReferences=[]
if ($g(tmp("projekt"))) { ; ulozime projekty
  s caa=0
  do { ; cyklus pres vsechny ID
    s sTC12=$$$getTagXC(.handle,"C12",.caa) ; vsechny ID
    continue:((sTC12="")&&(caa'=0))

    s sTC12a=$$$getSubTagStr(sTC12,"a")   ; cislo grantu CEP
    s sTC12b=$$$getSubTagStr(sTC12,"b")   ; poskytovatel grantu CEP
    s sTC12o=$$$getSubTagStr(sTC12,"o")   ; poskytovatel grantu z EU
    s sTC12n=$$$getSubTagStr(sTC12,"n")   ; cislo grantu EU

    ; exportovat jen projekty CEP a zahranicni
    s isCEP=(sTC12a'="")&&(sTC12b'="")
    s isFore=(sTC12o'="")&&(sTC12n'="")
    continue:'isCEP&&'isFore

    if isCEP {
      s awardNumber=sTC12a
      s poskname=##class(User.Util).sXlate("UN_POSKYT",sTC12b,"N",ipref,,3)      ; EN nazev poskytovatele z ciselniku
      s poskcode=sTC12b
    }
    else {
      s awardNumber=sTC12n
      s poskname=##class(User.Util).sXlate("UN_POSKYT_EU",sTC12o,"N",ipref,,3)   ; EN nazev poskytovatele z ciselniku
      s poskcode=sTC12o
    }

    ; ROR poskytovatele grantu z ciselniku EPCA_GA_DOI
    s ror=""
    if poskcode'="" {
      s ror=##class(User.Util).sXlate("EPCA_GA_DOI",poskcode,"N",ipref,"e")
      if ror'="" { s:'$f(ror,"http") ror="https://ror.org/"_ror }
    }

    ; dalsi polozky z autoritniho zaznamu projektu
    s sTC123=$$$getSubTagStr(sTC12,"3")
    s awardUri="", awardTitle=""
    if sTC123'="" && (##class(User.MARC).readLX(.hndlproj,sTC123)) { 
      if isCEP { 
        s cepID=##class(User.MARC).getTagX(.hndlproj,"230h")
        s:cepID'="" awardUri="https://www.isvavai.cz/cep?s=jednoduche-vyhledavani&ss=detail&n=0&h="_$replace($zcvt(cepID,"O","URL"),"/","%2F") }  ; escape neresi "/" proto replace 
      else { 
        s awardUri=##class(User.MARC).getTagX(.hndlproj,"300a") 
      }
      s awardTitle=##class(User.MARC).getTagX(.hndlproj,"230a")                     ; orig. nazev CZ/EN
      s:awardTitle="" awardTitle=##class(User.MARC).getTagX(.hndlproj,"430a")       ; nazev EN
    }

    s funder={}
    s funder.awardNumber=sTC12a
    s:awardUri'="" funder.awardUri=awardUri
    s:awardTitle'="" funder.awardTitle=awardTitle
    s funder.funderName=poskname    ; musi byt vyplneno, pro draft to API nekontroluje ale pak nelze zmenit draft -> findable
    if ror'="" {
      s funder.funderIdentifier=ror
      s funder.funderIdentifierType="ROR"
    }

    d fundingReferences.%Push(funder)

  } while (caa'=0)    
}
