  s sC90a=$$$getSubTagStr(sC90,"a")
  s infname=##class(User.Util).sXlate("UN_INFRASTRUKTURA",sC90a,"N",ipref)
  if infname'="" {
    s funder={}
    s funder.funderIdentifier=sC90a
    s funder.funderIdentifierType="OTHER"
    s funder.funderName=infname  ; musi byt vyplneno, pro draft to API nekontroluje ale pak nelze zmenit draft -> findable
    d fundingReferences.%Push(funder)
  }
} while c'=0*/
