s relatedIdentifiers=[]
s caa=0
do { ; cyklus pres vsechny vazby
  s sTU88=$$$getTagXC(.handle,"U88",.caa) ; vsechny ID
  continue:(sTU88="")
  s sTU88h=$$$getSubTagStr(sTU88,"h")
  continue:(sTU88h="")

  d relatedIdentifiers.%Push({"relationType": "IsDocumentedBy",         ; musi byt vyplneno
                              "relatedIdentifier": (sTU88h),
                              "relatedIdentifierType": "URL"})          ; musi byt vyplneno
} while (caa'=0)
if ($$$getTagX(.handle,"970b")="DATA"){
  ; ziskame si predchazejici verzi a u ni zjistime handle
  s sVerzePred=""
  s sVerzePo=""
  s retVer=..versionDataGetAll(.handle,.verze)
  for i=1:1:$l(retVer,"#") {  
    s ver=$p(retVer,"#",i)
    q:($f(ver,("*"_$$$HandleT001(handle)))) 
    s sVerzePred=ver     
  }
  for i=$l(retVer,"#"):-1:1 {
   s ver=$p(retVer,"#",i)
   q:($f(ver,("*"_$$$HandleT001(handle)))) 
   s sVerzePo=ver     
  }
  if (sVerzePred'="") {
    if ##class(User.MARC).readLX(.handleD,sVerzePred) {
      s doi=$$$getTagX(.handleD,"017a")  ; ne pres index doi, Cav nema vyplnene indikatory
      if doi'="" {
        s:'$f(doi,"doi.org") doi="https://doi.org/"_$$$trim(doi)
        d relatedIdentifiers.%Push({"relationType": "IsNewVersionOf",                ; musi byt vyplneno
                                    "relatedIdentifier": (doi),
                                    "relatedIdentifierType": "DOI"})                 ; musi byt vyplneno
      }

    }
  }
  if (sVerzePo'="") {
    if ##class(User.MARC).readLX(.handleP,sVerzePo) {
      s doi=$$$getTagX(.handleP,"017a")  ; ne pres index doi, Cav nema vyplnene indikatory
      if doi'="" {
        s:'$f(doi,"doi.org") doi="https://doi.org/"_$$$trim(doi)
        d relatedIdentifiers.%Push({"relationType": "IsPreviousVersionOf",           ; musi byt vyplneno
                                    "relatedIdentifier": (doi),
                                    "relatedIdentifierType": "DOI"})                 ; musi byt vyplneno
      }
    }
  } 
}
