; The landing page
; s Cav dohodnuto ze pujde o persistentni link do IPACu
; udelame to podle handle.net
s ictx=$zcvt(ipref,"l")
s language=+##class(User.Util).getServerLanguage(ipref)
s idx=##class(User.Util).objectName2lname($$$HandleClass(handle))_"*"_$$$HandleT001(handle)
if 'bIpacContext { d ##class(i2.init).batchinit(ictx,language) }
s sBaseURL=##class(i2.html.tpl).getBaseURL()
; linku na detail zaznamu v ipacu 
s hlink=sBaseURL_##class(i2.html.tpl).getRecordURL(idx)
s hlink=##class(User.Util).strswap(hlink,"&amp;","&")
if 'bIpacContext { k %ipac2 } ; pokusime se hned po sobe uklidit, jsme nejspis v DUI, deinicializace
s data.attributes.url=hlink

; https://schema.datacite.org/meta/kernel-4.6/
s data.attributes.schemaVersion="http://datacite.org/schema/kernel-4"


; POZOR neni ve schematu - nejspis to bude API ignorovat
; je to z pozadavku Cav na export datacite do IPACu
; https://asep-portal.lib.cas.cz/a_porady/naceneni_2023/0544591_dataset_JSON.pdf
s data.attributes.providerId=$zcvt(providerId,"L")
s data.attributes.clientId=$zcvt(clientId,"L")
s data.attributes.agency="datacite"

s str=obj.%ToJSON()
q str

s data("doiurl")="",data("handle.net")="",data("doi")=""

s nC=##class(User.MARC).recordLineCountX(.handle) ; ziskani poctu radku v zaznamu 
for i=1:1:nC { 
  s lsLine=##class(User.MARC).getLineX(.handle,i) 
  continue:lsLine="" 

  s sTag=$e(lsLine,1,3)
  if (sTag="017") {
    ; nacteme si DOI
    s:($$$getSubTagStr(lsLine,"2")="DOI") sDOI=$$$getSubTagStr(lsLine,"a")   
    continue:(sDOI="")

    ; osetrime obe varianty DOI s a bez url
    if ($l(sDOI,"/")>5) {
      s data("doiurl")=sDOI
      s data("doi")=$p(sDOI,"/",4,999)
    }
    else {
      s data("doiurl")="https://doi.org/"_sDOI
      s data("doi")=sDOI
    }
  } 
  elseif (sTag="101") {
    ; <language>  volitelné   101a
    s iso6392=$$$getSubTagStr(lsLine,"a")
    if iso6392'="" {
      s iso6391=..getLangCode(iso6392) 
      s:(iso6391'="") data("jazyk")=iso6391
    }
  }
  elseif (sTag="200") { 
    s title=$$$getSubTagStr(lsLine,"a")                          ; nazev
    ; 22.05.26 jk; vymazat formatovaci znaky
    d ##class(rep.epca.exportBase).symClearFormatInfoStr(.title)
    s data("nazev")=title
    s data("nazevAlternativni")=$$$getSubTagStr(lsLine,"e")      ; alternativni nazev
  }
  elseif (sTag="541") {
    ; nacteme si preklad nazvu - 541a, lang="en" -541zv
    s:($$$getSubTagStr(lsLine,"z")="eng") data("nazevPreklad")=$$$getSubTagStr(lsLine,"a")
  }
  elseif (sTag="608") {
    ; <resourceType> povinné     608a    Typ datových souborů
    s data("typSouboru")=$$$getSubTagStr(lsLine,"a")   
  }
  elseif (sTag="610") {
    ; priznak, jestli exportovat subjekt
    s:($$$getSubTagStr(lsLine,"a")'="") data("subjekt")=1
  }
  elseif (sTag="C12") {
    s:($$$getSubTagStr(lsLine,"a")'="") data("projekt")=1
  }
  elseif (sTag="C15") {
    s data("abstractCz")=$$$trim($replace($$$getSubTagStr(lsLine,"a"),"\n"," "))
    s data("abstractEn")=$$$trim($replace($$$getSubTagStr(lsLine,"b"),"\n"," "))
  }
  elseif (sTag="C26") {
    s:($$$getSubTagStr(lsLine,"x")'="") bSubject=1
    s data("C26x")=##class(User.Util).sXlate("EPCA_OECDALL",$$$getSubTagStr(lsLine,"x"),,ipref)
    s data("C26y")=##class(User.Util).sXlate("EPCA_OECDALL",$$$getSubTagStr(lsLine,"y"),,ipref)
    s data("C26z")=##class(User.Util).sXlate("EPCA_OECDALL",$$$getSubTagStr(lsLine,"z"),,ipref)      
  }
  elseif (sTag="C60") {
    ; handle. net
    s data("handle.net")=$$$getSubTagStr(lsLine,"a")   
  }
  elseif (sTag="T16") {
    ; <publicationYear> povinné
    s data("rokPublikace")=$$$getSubTagStr(lsLine,"r")   
  }
  elseif (sTag="U03") {
    ; <version>   volitelné   U03a
    s data("verze")=$zstrip($$$getSubTagStr(lsLine,"a"),"<","0")
  }
  elseif (sTag="U22") { 
    s data("datumOd")=$e($$$getSubTagStr(lsLine,"a"),1,8)
    s data("datumDo")=$e($$$getSubTagStr(lsLine,"b"),1,8)
  }
  elseif ((sTag="700") || (sTag="701") || (sTag="702")) {
    ; zpracovani udaju o autorovi
    d ..handle2jsonPrepareAuth(ipref,.data,lsLine)  
  }
}

s sUstav=$$$getSubTagStr(.pAutor,"p")
s sPrijmeni=$$$getSubTagStr(.pAutor,"a")
s sJmeno=$$$getSubTagStr(.pAutor,"b")
s sLink=$$$getSubTagStr(.pAutor,"3")
s sOrcid="",sRor="",sRorNazev=sUstav, sWOS="",sSCOPUS=""

if (sLink'="") {
  if ##class(User.MARC).readLX(.handlea70X,sLink) {
    ; pokud se nam podarilo autoritu otevrit
    s caa=0
    do { ; cyklus pres vsechny ID
      s sT035=$$$getTagXC(.handlea70X,"035",.caa) ; vsechny ID
      continue:((sT035="")&&(caa'=0))
      s sT035a=$$$getSubTagStr(sT035,"a")
      s sT0352=$$$getSubTagStr(sT035,"2")
      if (sT0352="ORCID") {
        ; mam orcid   035     $a 0000-0002-4606-1218 $2 ORCID 
        s sOrcid=sT035a
      }        
      elseif (sT0352="WOS") {
        ; mam wos  035       $a F-5169-2014 $2 WOS 
        s sWOS=sT035a
      } 
      elseif (sT0352="SCOPUS") {
        ; mam scopus      035     $a 6603184151  $2 SCOPUS 
        s sSCOPUS=sT035a
      }          
    }while (caa'=0)
  }
}

s sUstav=$zcvt($zstrip(sUstav,"<>W"),"L")  ; ziskame zkratku ustavu
if (sUstav'="") {
  s sTerm=" "_sUstav_" (o)"               ; seskladame termini pro vyhledani konkretniho ustavu
  s sPracid=##class(User.MARC).getIDByIndex(ipref_"UnAuth","aucr",sTerm)
  if (sPracid'=0) {
    ; pokud id neni 0 - mam ustav a muzeme jej otevrit
    if ##class(User.MARC).getDATAX(.hndla,sPracid)
    { ; pokud se podarilo otevrit zaznam pracoviste, nacteme informace
      ; ziskame nazvy pracoviste v jazykovych mutacich
      s xx="0"
      do {
        s sT410=$$$getTagXC(.hndla,"410",.xx) ; vsechny variantni nazvy
        continue:((sT410="")&&(xx'=0))
        if (sT410'="") {
          ; pokud mame vyplnene data, muzeme provadet akce 
          s sT4108=$$$getSubTagStr(sT410,"8")
          s:(sT4108="eng") sRorNazev=$$$getSubTagStr(sT410,"a")
        }
      } while (xx'=0)
    }
    s sRor=..getAuthROR(.hndla)
  }
}   

; osetrime si pocet autoru
s pocetAutoru=$g(data("autori","pocet"),-1)
s pocetAutoru=pocetAutoru+1
s data("autori","pocet")=pocetAutoru

s:(sPrijmeni'="") data("autor",pocetAutoru,"celejmeno")=sPrijmeni_", "_sJmeno
