s:(sOrcid'="") data("autor",pocetAutoru,"orcid")="https://orcid.org/"_sOrcid
s:(sWOS'="") data("autor",pocetAutoru,"wos")="https://www.webofscience.com/wos/author/record/"_sWOS
s:(sSCOPUS'="") data("autor",pocetAutoru,"scopus")="https://www.scopus.com/authid/detail.uri?authorId="_sSCOPUS
s:(sRorNazev'="") data("autor",pocetAutoru,"rornazev")=sRorNazev
s:(sRor'="") data("autor",pocetAutoru,"ror")="https://ror.org/"_sRor

s ret=""
s c="0"
do {
  s s035=$$$getTagXC(.handle,"035",.c)
  continue:(s035="")
  if (s035'="") {
    s s0352=$$$getSubTagStr(s035,"2")
    if (s0352="PIDROR") {
      s ret=$$$getSubTagStr(s035,"a")
      q
    }
  }
} while (c'=0)

q ret

s ipref=##class(User.Util).getClassPrefixParam($$$HandleClass(handle))
s language=3  ; EN

; 31.08.26 jk; zapojen ciselnik UT_ASEP_LICENCECC
s sC81b=$$$getTagX(.handle,"C81b")

s (rights,rightsUri,schemeUri,rightsIdentifier,rightsIdentifierScheme,lang)=""
if ##class(User.Util).sXlate("UT_ASEP_LICENCECC",sC81b,"E",ipref)="@exist@" {
  s rights=##class(User.Util).sXlate("UT_ASEP_LICENCECC",sC81b,"N",ipref,,language)
  s rightsUri=##class(User.Util).sXlate("UT_ASEP_LICENCECC",sC81b,"N",ipref,"o",language)
  s schemeUri="https://spdx.org/licenses/"
  s rightsIdentifier=sC81b
  s rightsIdentifierScheme="SPDX"
  s lang="en"
}
else {
  ; dalsi hodnoty sC81b zjisteny z dat CavUnEpca 

  ; 12.08.26 ln; popdpora licence s i bez pomlcek
  s sC81b=$tr(sC81b,"-"," ")
  s sC81c=$$$getTagX(.handle,"C81c")
  s sC81e=$$$getTagX(.handle,"C81e")
  s sC60a=$$$getTagX(.handle,"C60a")  ; handle.net

  ; hodnoty sC81b zjisteny z dat CavUnEpca
  if sC81b="CC0 1.0" {
    s rights="Creative Commons Zero v1.0 Universal"
    s rightsUri="https://creativecommons.org/publicdomain/zero/1.0/legalcode"
    s schemeUri="https://spdx.org/licenses/"
    s rightsIdentifier="CC0-1.0"
    s rightsIdentifierScheme="SPDX"
    s lang="en"
  }
  elseif sC81b="CC BY 4.0" {
    s rights="Creative Commons Attribution 4.0 International"
    s rightsUri="https://creativecommons.org/licenses/by/4.0/legalcode"
    s schemeUri="https://spdx.org/licenses/"
    s rightsIdentifier="CC-BY-4.0"
    s rightsIdentifierScheme="SPDX"
    s lang="en"
  }
  elseif sC81b="CC BY ND 4.0" {
    s rights="Creative Commons Attribution No Derivatives 4.0 International"
    s rightsUri="https://creativecommons.org/licenses/by-nd/4.0/legalcode"
    s schemeUri="https://spdx.org/licenses/"
    s rightsIdentifier="CC-BY-ND-4.0"
    s rightsIdentifierScheme="SPDX"
    s lang="en"
  }
  elseif sC81b="CC BY SA 4.0" {
    s rights="Creative Commons Attribution Share Alike 4.0 International"
    s rightsUri="https://creativecommons.org/licenses/by-sa/4.0/legalcode"
    s schemeUri="https://spdx.org/licenses/"
    s rightsIdentifier="CC-BY-SA-4.0"
    s rightsIdentifierScheme="SPDX"
    s lang="en"
  }
  elseif (sC81b="CC BY NC 4.0") || (sC81b="BY NC") {
    s rights="Creative Commons Attribution Non Commercial 4.0 International"
    s rightsUri="https://creativecommons.org/licenses/by-nc/4.0/legalcode"
    s schemeUri="https://spdx.org/licenses/"
    s rightsIdentifier="CC-BY-NC-4.0"
    s rightsIdentifierScheme="SPDX"
    s lang="en"
  }
  elseif (sC81b="CC BY NC ND 4.0") || (sC81b="BY NC ND") {
    s rights="Creative Commons Attribution Non Commercial No Derivatives 4.0 International"
    s rightsUri="https://creativecommons.org/licenses/by-nc-nd/4.0/legalcode"
    s schemeUri="https://spdx.org/licenses/"
    s rightsIdentifier="CC-BY-NC-ND-4.0"
    s rightsIdentifierScheme="SPDX"
    s lang="en"
  }
  elseif (sC81b="CC BY NC SA 4.0") || (sC81b="BY NC SA") {
    s rights="Creative Commons Attribution Non Commercial Share Alike 4.0 International"
    s rightsUri="https://creativecommons.org/licenses/by-nc-sa/4.0/legalcode"
    s schemeUri="https://spdx.org/licenses/"
    s rightsIdentifier="CC-BY-NC-SA-4.0"
    s rightsIdentifierScheme="SPDX"
    s lang="en"
  }
  elseif sC81c'="" {
    ; jina licence
    s rights="Academic Free License v1.1"
    s rightsUri="https://spdx.org/licenses/AFL-1.1.html"
    s schemeUri="https://spdx.org/licenses/"
    s rightsIdentifier="AFL-1.1"
    s rightsIdentifierScheme="SPDX"
  }
  elseif sC81e'="" {
    ; vlastni licence
    s rights="Dataset has its own license"
    s rightsUri=sC60a
  }
}

