  if rightsIdentifierScheme'="" { s ret=ret_" rightsIdentifierScheme="""_##class(User.Util).XMLfixup(rightsIdentifierScheme)_""""  }
  if rightsIdentifier'="" { s ret=ret_" rightsIdentifier="""_##class(User.Util).XMLfixup(rightsIdentifier)_"""" }
  if rightsUri'="" { s ret=ret_" rightsURI="""_##class(User.Util).XMLfixup(rightsUri)_"""" }
