; 29.07.24 jk; doplneno vyhodnoceni podle charset
s charset=$$$GETREQVAR("charset")
if pnWhat=$$$I2ExportHdr    {
  if charset="CP1250" { d ##class(i2.export).outputAdd("<?xml version=""1.0"" encoding=""windows-1250""?>"_$c(10),pnOutFmt) }
  elseif charset="UTF8" { d ##class(i2.export).outputAdd("<?xml version=""1.0"" encoding=""UTF-8""?>"_$c(10),pnOutFmt) }
  else { d ##class(i2.export).outputAdd("<?xml version=""1.0"" encoding=""UTF-8""?>"_$c(10),pnOutFmt) }   ; default UTF8

  q
}
