  s caa=0
  do { ; cyklus pres vsechny vazby
    s sTU88=$$$getTagXC(.handle,"U88",.caa) ; vsechny ID
    continue:((sTU88="")&&(caa'=0))
    s sTU88h=$$$getSubTagStr(sTU88,"h")
    s:(sTU88h'="") relatedIdentifiers=relatedIdentifiers_$$$spc(4)_"<relatedIdentifier relatedIdentifierType=""URL"" relationType=""IsDocumentedBy"">"_sTU88h_"</relatedIdentifier>"_$c(10)
  } while (caa'=0)
}

if (($$$getTagX(.handle,"970b")="DATA")&&(pTyp="Datacite")) {
  ; ziskame predchazejici a nasledujici verzi
  s sVerzePred="", sVerzePo=""
  s retVer=..versionDataGetAll(.handle)
  for i=1:1:$l(retVer,"#") {  
    s ver=$p(retVer,"#",i)
    q:($f(ver,("*"_$$$HandleT001(handle)))) 
    s sVerzePred=ver     
  }
  for i=$l(retVer,"#"):-1:1 {
    s ver=$p(retVer,"#",i)
    q:($f(ver,("*"_$$$HandleT001(handle)))) 
    s sVerzePo=ver     
  }

  if (sVerzePred'="") {
    if ##class(User.MARC).readLX(.handleD,sVerzePred) {
      s doi=$$$getTagX(.handleD,"017a")  ; ne pres index doi, Cav nema vyplnene indikatory
      if doi'="" {
        s:'$f(doi,"doi.org") doi="https://doi.org/"_$$$trim(doi)
        s relatedIdentifiers=relatedIdentifiers_$$$spc(4)_"<relatedIdentifier relatedIdentifierType=""DOI"" relationType=""IsNewVersionOf"">"_doi_"</relatedIdentifier>"_$c(10)
      }
    }
  }

  if (sVerzePo'="") {
    if ##class(User.MARC).readLX(.handleP,sVerzePo) {
      s doi=$$$getTagX(.handleP,"017a")  ; ne pres index doi, Cav nema vyplnene indikatory
      if doi'="" {
        s:'$f(doi,"doi.org") doi="https://doi.org/"_$$$trim(doi)
        s relatedIdentifiers=relatedIdentifiers_$$$spc(4)_"<relatedIdentifier relatedIdentifierType=""DOI"" relationType=""IsPreviousVersionOf"">"_doi_"</relatedIdentifier>"_$c(10)
      }
    }
  }

  // 1.12.23 tt; na zaklade pozadavku drobne upravy zakazky 2022 (29.11.23) upraveno
  ///s sTU03a=$zstrip($$$getTagX(.handle,"U03a"),"<","0") ; ziskame verzi datasetu
  //d:(sTU03a'="") ##class(i2.export).outputAdd($$$spc(2)_"<version>"_sTU03a_"</version>")
}

if relatedIdentifiers'="" {
