   }  
   if geo'="" {
     s:geoLocations="" geoLocations=$$$spc(4)_"<geoLocations>"_$c(10)
     s geoLocations=geoLocations_$$$spc(6)_"<geoLocation>"_$c(10)
     s geoLocations=geoLocations_$$$spc(6)_"<geoLocationPlace>"_##class(User.Util).XMLfixup(geo)_"</geoLocationPlace>"_$c(10)
     s geoLocations=geoLocations_$$$spc(6)_"</geoLocation>"_$c(10)
   }
 } while c'=0
