if (bProjekt)
{
  d:(pTyp="Datacite") ##class(i2.export).outputAdd($$$spc(2)_"<fundingReferences>"_$c(10),pnOutFmt)
  s caa=0
  d { ; cyklus pres vsechny ID
    s sTC12=$$$getTagXC(.handle,"C12",.caa) ; vsechny ID
    continue:((sTC12="")&&(caa'=0))

    s sTC12a=$$$getSubTagStr(sTC12,"a")   ; cislo grantu CEP
    s sTC12b=$$$getSubTagStr(sTC12,"b")   ; poskytovatel grantu CEP
    s sTC12o=$$$getSubTagStr(sTC12,"o")   ; poskytovatel grantu z EU
    s sTC12n=$$$getSubTagStr(sTC12,"n")   ; cislo grantu EU

    ; exportovat jen projekty CEP a zahranicni
    s isCEP=(sTC12a'="")&&(sTC12b'="")
    s isFore=(sTC12o'="")&&(sTC12n'="")
    continue:'isCEP&&'isFore

    if isCEP {
      s awardNumber=sTC12a
      s poskname=##class(User.Util).sXlate("UN_POSKYT",sTC12b,"N",ipref,,3)      ; EN nazev poskytovatele z ciselniku
      s poskcode=sTC12b
    }
    else {
      s awardNumber=sTC12n
      s poskname=##class(User.Util).sXlate("UN_POSKYT_EU",sTC12n,"N",ipref,,3)   ; EN nazev poskytovatele z ciselniku
      s poskcode=sTC12o
    }

    ; ROR poskytovatele grantu z ciselniku EPCA_GA_DOI
    s ror=""
    if poskcode'="" {
      s ror=##class(User.Util).sXlate("EPCA_GA_DOI",poskcode,"N",ipref,"e")
      if ror'="" { s:'$f(ror,"http") ror="https://ror.org/"_ror }
    }

    ; dalsi polozky z autoritniho zaznamu projektu
    s sTC123=$$$getSubTagStr(sTC12,"3")
    s awardUri="", awardTitle=""
     if sTC123'="" && (##class(User.MARC).readLX(.hndlproj,sTC123)) { 
       if isCEP { 
         s cepID=##class(User.MARC).getTagX(.hndlproj,"230h")
         s:cepID'="" awardUri="https://www.isvavai.cz/cep?s=jednoduche-vyhledavani&ss=detail&n=0&h="_$replace($zcvt(cepID,"O","URL"),"/","%2F") }  ; escape neresi "/" proto replace 
       else { 
         s awardUri=##class(User.MARC).getTagX(.hndlproj,"300a") 
       }
       s awardTitle=##class(User.MARC).getTagX(.hndlproj,"230a")                     ; orig. nazev CZ/EN
       s:awardTitle="" awardTitle=##class(User.MARC).getTagX(.hndlproj,"430a")       ; nazev EN
     }

    if pTyp="Datacite" {
      d ##class(i2.export).outputAdd($$$spc(4)_"<fundingReference>"_$c(10),pnOutFmt)
      d ##class(i2.export).outputAdd($$$spc(6)_"<funderName>"_##class(User.Util).XMLfixup(poskname)_"</funderName>"_$c(10),pnOutFmt)
      d ##class(i2.export).outputAdd($$$spc(6)_"<funderIdentifier funderIdentifierType=""ROR"">"_##class(User.Util).XMLfixup(ror)_"</funderIdentifier>"_$c(10),pnOutFmt)
      if awardUri'="" { d ##class(i2.export).outputAdd($$$spc(6)_"<awardNumber awardUri="""_##class(User.Util).XMLfixup(awardUri)_""">"_##class(User.Util).XMLfixup(sTC12a)_"</awardNumber>"_$c(10),pnOutFmt) }
      else { d ##class(i2.export).outputAdd($$$spc(6)_"<awardNumber>"_##class(User.Util).XMLfixup(sTC12a)_"</awardNumber>"_$c(10),pnOutFmt) }
      if awardTitle'="" { d ##class(i2.export).outputAdd($$$spc(6)_"<awardTitle>"_##class(User.Util).XMLfixup(awardTitle)_"</awardTitle>"_$c(10),pnOutFmt) }
      d ##class(i2.export).outputAdd($$$spc(4)_"</fundingReference>"_$c(10),pnOutFmt)
    }
    elseif pTyp="Openaire" {
      d ##class(i2.export).outputAdd($$$spc(2)_"<contributor contributorType=""Funder"">"_$c(10),pnOutFmt)
      d ##class(i2.export).outputAdd($$$spc(4)_"<contributorName>"_##class(User.Util).XMLfixup(poskname)_"</contributorName>"_$c(10),pnOutFmt)
      d:(awardNumber'="") ##class(i2.export).outputAdd($$$spc(4)_"<nameIdentifier nameIdentifierScheme=""info"">"_##class(User.Util).XMLfixup(awardNumber)_"</nameIdentifier>"_$c(10),pnOutFmt)
      d ##class(i2.export).outputAdd($$$spc(2)_"</contributor>"_$c(10),pnOutFmt)
    }
  } while (caa'=0)

  d:(pTyp="Datacite") ##class(i2.export).outputAdd($$$spc(2)_"</fundingReferences>"_$c(10),pnOutFmt)
}    

